n("עורי", "עורי היא מילה מתוך שירת דבורה בספר שופטים, עורי עורי דבורה, קריאה להתעורר ולשיר. השם עברי, והוא נשמע עתיק וחי גם יחד. השם ניתן לבנות, והוא נדיר. מאותו שורש בא גם השם עירית.", ["עירית"])
n("מני", "מני הוא צורת חיבה של מנחם ושל מנשה, ובקהילות מסוימות גם שם בפני עצמו. השם מנחם פירושו מי שמנחם ומביא נחמה. מני היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנים.", ["מנחם", "מנשה"])
n("נתנאלה", "נתנאלה הוא הצורה הנשית של נתנאל, שם עברי שבנוי מהמילים נתן ואל, ופירושו אלוהים נתן. השם נשמע חגיגי ומלא הודיה. השם ניתן לבנות, והוא נדיר. מאותו שורש באים גם השמות נתן ויונתן.", ["נתנאל", "נתן"])
n("צמח", "צמח הוא שם עברי מהמילה צמח, כל דבר שגדל מהאדמה. בספר זכריה צמח הוא כינוי לאיש שיבנה את המקדש, ובמסורת הוא סמל לגאולה. השם ניתן לבנים, והוא היה נפוץ בעיקר בקהילות של יהודי עיראק.", [])
n("צהלה", "צהלה הוא שם עברי מהמילה צהלה, שמחה גדולה וקריאה של שמחה. מאותה מילה באים גם השמות צהל וצהלי. צהלה היא גם שם של שכונה בצפון תל אביב. השם ניתן לבנות, והוא נדיר.", ["צהל", "צהלי"])
n("אמית", "אמית הוא שם עברי מהמילה עמית, חבר או שותף, בכתיב עם האות א. בכתיב הזה השם נשמע קרוב גם למילה אמת. השם ניתן גם לבנים וגם לבנות, והוא נדיר. הכתיב הנפוץ יותר הוא עמית.", ["עמית", "אמיתי"])
n("הינדי", "הינדי הוא צורה יידית של הינדה, שם שבא מהמילה הגרמנית הינדין, איילה. ביידיש השם הזה בא לפעמים יחד עם השם העברי אילה. השם ניתן לבנות, והוא נדיר מאוד היום.", ["הינדא", "איילה"])
n("אידו", "אידו הוא כתיב של עידו, שם עברי שקשור כנראה למילה עדות או לשורש ע־ד־ה. בכתיב עם האות א השם נשמע בינלאומי יותר. השם ניתן לבנים, והכתיב הזה נדיר בארץ.", ["עידו"])
n("נסה", "נסה הוא שם עברי חדש מהמילה נס, דבר שקורה מעבר לטבע, וגם דגל. השם קצר ופשוט, והוא ניתן לבנות. הוא קרוב לשמות נס ונסיה, ויש שקושרים אותו גם לשם האנגלי נסה.", ["נסיה", "נס"])
n("קוה", "קוה הוא שם עברי נדיר מהשורש ק־ו־ה, תקווה וציפייה. במסורת מוכר הפסוק קוה אל ה׳, שמבטא אמונה וסבלנות. השם ניתן לבנים, והוא נשמע עתיק ופשוט.", [])
n("אלירוי", "אלירוי הוא שם עברי חדש, וכנראה הוא בנוי מהמילים אלי ורועי, ופירושו האל שלי הוא הרועה שלי. השם קרוב לשמות כמו רועי ואלרוי. השם ניתן לבנים, והוא נדיר.", ["אלרוי", "רועי"])
n("ניתן", "ניתן הוא שם עברי חדש מהשורש נ־ת־ן, ופירושו מי שניתן במתנה. מאותו שורש באים גם השמות נתן, נתנאל ויונתן. השם ניתן לבנים, והוא נדיר. יש בו תחושה של הודיה על ילד.", ["נתן", "נתנאל"])
n("פרי", "פרי הוא שם עברי מהמילה פרי, מה שהעץ נותן. השם מביא תמונה של שפע ושל צמיחה. השם ניתן גם לבנים וגם לבנות, והוא נדיר. מאותו שורש באים גם השמות פוריה ופריאל.", ["פריאל", "פוריה"])
n("כוכב", "כוכב הוא שם עברי מהמילה כוכב, אור קטן בשמי הלילה. השם היה נפוץ בעיקר בקהילות של יהודי תימן ופרס, גם לבנות וגם לבנים. היום הוא נדיר, וקרובה אליו צורת הנקבה כוכבה.", ["כוכבה"])
n("אליצור", "אליצור הוא שם מקראי שבנוי מהמילים אלי וצור, ופירושו אלוהים הוא הסלע שלי. בספר במדבר אליצור בן שדיאור הוא נשיא שבט ראובן. השם ניתן לבנים, והוא נדיר. מאותה מילה באים גם השמות צור וצוריאל.", ["צור", "צוריאל"])
n("גלאור", "גלאור הוא שם עברי חדש שבנוי מהמילים גל ואור, ופירושו גל של אור. השם נשמע בהיר וקליל, והוא ניתן גם לבנים וגם לבנות. הוא נדיר, וקרובים אליו שמות כמו גל ואור.", ["גל", "אור"])
n("תאה", "תאה הוא שם חדש ונדיר, וכנראה הוא צורה של תיאה, שם יווני שפירושו אלה. במיתולוגיה היוונית תיאה היא אחת הטיטאניות, אמם של השמש והירח. השם ניתן לבנות.", ["תיאה", "תאיה"])
n("אדריאנה", "אדריאנה הוא הצורה הנשית של אדריאן, שם לטיני שקשור לעיר אדריה שליד הים האדריאטי. השם נפוץ באיטלקית, ברומנית ובשפה הספרדית. בארץ הוא נדיר, והוא ניתן לבנות.", ["אדריאן"])
n("ריצ'רד", "ריצ׳רד הוא שם בינלאומי ממקור גרמני, שבנוי מהמילים שלטון וחזק, ופירושו שליט חזק. השם מוכר בזכות כמה מלכים של אנגליה, כמו ריצ׳רד לב הארי. בארץ השם נדיר, והוא ניתן לבנים.", [])
n("שונית", "שונית היא רכס של אלמוגים בים, שבו חיים דגים ויצורי ים רבים. בארץ מוכרת השונית באילת. השם עברי וחדש, והוא ניתן לבנות. בצליל הוא קרוב לשמות כמו שני ושנית.", ["שני", "שנית"])
n("חזקיה", "חזקיה הוא שם מקראי שפירושו ה׳ חיזק. חזקיהו היה מלך יהודה, ובספר מלכים נאמר שעשה הישר בעיני ה׳. בימיו נחפרה נקבת השילוח בירושלים. השם ניתן לבנים, ומוכרת גם הצורה חזקיהו.", ["חזקיהו"])
n("לי אל", "לי אל הוא שם עברי חדש שבנוי מהמילים לי ואל, ופירושו האל שלי. השם נכתב גם ליאל ולי־אל, והוא נשמע רך ושמח. השם ניתן לבנות, והכתיב בשתי מילים נדיר בארץ.", ["ליאל", "לי-אל"])
n("יוהד", "יוהד הוא שם חדש ונדיר, ואולי הוא בנוי מהמילים יה והוד, ופירושו ההוד של אלוהים. בצליל הוא קרוב לשמות יהודה והוד. השם ניתן לבנים, והוא נשמע עתיק ומכובד.", ["יהודה", "הוד"])
n("אתאל", "אתאל הוא שם נדיר, ואולי הוא צורה של אתל, שם אנגלי עתיק שפירושו אציל. בעברית אפשר לקרוא בו גם את המילים את ואל. השם ניתן לבנות, והוא נשמע עתיק ושונה.", [])
n("סוזן", "סוזן היא צורה אירופית של שושנה, שם עברי שפירושו פרח השושן. השם נפוץ באנגלית ובצרפתית, ובשפות אחרות מוכרות הצורות סוזנה וסוזי. בארץ השם נדיר, והוא ניתן לבנות.", ["סוזנה", "שושנה"])
n("דקלה", "דקלה הוא שם עברי מהמילה דקל, עץ התמר הגבוה. העץ הזה היה סמל של הארץ ושל פריון. השם ניתן לבנות, והוא היה נפוץ בארץ בשנות השבעים והשמונים. מוכרים גם הכתיב דיקלה והשם דקל.", ["דקל", "דיקלה"])
n("רגינה", "רגינה היא המילה הלטינית למלכה. השם נפוץ בשפות רבות באירופה, והוא היה מוכר גם בקהילות יהודיות במרכז אירופה, לפעמים כתרגום של השם מלכה. השם ניתן לבנות, והוא נדיר בארץ.", ["מלכה"])
n("זבולון", "זבולון הוא אחד משנים עשר בני יעקב, בנה של לאה. בספר בראשית לאה אומרת על הולדתו שעכשיו בעלה יזבלני, כלומר יגור איתה. שבט זבולון ישב בגליל ליד הים. השם ניתן לבנים.", [])
n("שמאי", "שמאי הוא שמו של אחד מגדולי החכמים בתקופת בית שני, שהיה בן זוגו של הלל. בית שמאי ובית הלל נחלקו במחלוקות רבות במשנה. השם ניתן לבנים, והוא נדיר, ויש שקושרים אותו לשורש ש־מ־ע.", ["הלל"])
n("לייב", "לייב היא המילה היידית לאריה, והיא באה מהמילה הגרמנית לווה. ביידיש השם בא לרוב יחד עם השם העברי אריה, כמו אריה לייב. השם ניתן לבנים, והוא נפוץ בעיקר בקהילות חרדיות. קרובים אליו השמות לביא וליב.", ["אריה", "לביא"])
n("אבגיל", "אבגיל הוא כתיב של אביגיל, שם מקראי שפירושו אבי הוא שמחתי. אביגיל הייתה אשה חכמה שהפכה לאשתו של דוד המלך. השם ניתן לבנות, והכתיב הזה נדיר בארץ.", ["אביגיל", "אביגל"])
n("ג'יה", "ג׳יה הוא שם חדש ונדיר, וכנראה הוא צורה של גאיה, אמא האדמה במיתולוגיה היוונית. באיטלקית ג׳יה היא גם צורה קצרה של ג׳ויה, שמחה. השם ניתן לבנות, והוא נשמע קצר וחם.", ["ג'וי"])
n("להיה", "להיה הוא שם חדש ונדיר, וכנראה הוא בנוי מהמילים לה ויה, ופירושו לאלוהים. השם קרוב בצליל לשמות כמו ליהיא וליה. השם ניתן לבנות, והוא נשמע רך ומוזיקלי.", ["ליהיא", "ליהי"])
n("סבטלנה", "סבטלנה הוא שם רוסי שבא מהמילה סווט, אור, ופירושו מאירה או בהירה. השם היה נפוץ מאוד בברית המועצות, וצורת החיבה שלו היא סווטה. בארץ השם הגיע עם העלייה, והוא ניתן לבנות.", [])
n("אורנה", "אורנה הוא שם עברי מהמילה אורן, עץ מחטני ירוק שגדל בהרים וביערות של הארץ. השם היה נפוץ בארץ בשנות הארבעים והחמישים. אורנה ניתן לבנות, וקרובים אליו השמות אורן ואורנית.", ["אורן", "אורנית"])
n("ויטלי", "ויטלי הוא שם סלאבי שבא מהשם הלטיני ויטליס, מלא חיים. השם נפוץ ברוסית ובאוקראינית, וצורת החיבה שלו היא ויטיה. בארץ השם הגיע עם העלייה מברית המועצות, והוא ניתן לבנים.", ["ויטל"])
n("עפרה", "עפרה הוא שם עברי מהמילה עופר, צבי צעיר, ויש שקושרים אותו גם למילה עפר. בספר שופטים עפרה היא העיר של גדעון, שבה ראה את המלאך. השם ניתן לבנות, והוא היה נפוץ בארץ בשנות החמישים.", ["עופר", "עופרה"])
n("שבתאי", "שבתאי הוא שם עברי מהמילה שבת, שניתן לפעמים לילדים שנולדו בשבת. שבתאי הוא גם שמו של כוכב הלכת עם הטבעות. השם היה נפוץ בעיקר בקהילות של יהודי יוון ותורכיה, והוא ניתן לבנים.", [])
n("ולנטינה", "ולנטינה הוא שם לטיני שבא מהמילה ולנס, חזק ובריא. השם נפוץ באיטלקית, ברוסית ובשפה הספרדית. ולנטינה טרשקובה הייתה האשה הראשונה בחלל. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("אורנית", "אורנית הוא שם עברי מהמילה אורן, עץ מחטני ירוק. אורנית היא גם שם של יישוב בשומרון. השם היה נפוץ בארץ בשנות השישים, והוא ניתן לבנות. קרובים אליו השמות אורנה ואורן.", ["אורנה", "אורן"])
n("הנרי", "הנרי הוא שם בינלאומי ממקור גרמני שבנוי מהמילים בית ושלטון, ופירושו שליט הבית. זה היה שמם של מלכים רבים באנגליה ובצרפת. בארץ השם נדיר, והוא ניתן לבנים.", [])
n("פאני", "פאני היא צורת חיבה של פרנסס, שם שפירושו צרפתייה או אדם חופשי. השם היה נפוץ באנגליה ובצרפת במאה התשע עשרה. בארץ השם נדיר, והוא ניתן לבנות. הוא נשמע עתיק וחמוד.", [])
n("קטיה", "קטיה היא צורת חיבה רוסית של יקטרינה, הצורה הרוסית של קתרין. השם נפוץ ברוסית, באוקראינית ובפולנית. בארץ השם הגיע עם העלייה, והוא ניתן לבנות. מוכרות גם הצורות קטי וקייט.", ["קטי", "קייט"])
n("חמוטל", "חמוטל היא אמם של שני מלכי יהודה, יהואחז וצדקיהו, בספר מלכים. יש שקוראים בשם את המילים חם וטל, טל חם. השם ניתן לבנות, והוא נדיר, אבל מוכר בארץ בזכות כמה נשים ידועות.", [])
n("עובד", "עובד הוא בנם של רות ובועז, וסבו של דוד המלך. במגילת רות השכנות הן שנותנות לו את שמו. השם בא מהשורש ע־ב־ד, עבודה ועבודת ה׳. השם ניתן לבנים, וקרוב אליו השם עובדיה.", ["עובדיה"])
n("ראול", "ראול הוא שם ספרדי וצרפתי שבא מגרמנית עתיקה, ופירושו כנראה זאב יועץ. השם נפוץ באמריקה הלטינית ובספרד. בארץ השם נדיר, והוא ניתן לבנים. בעברית הוא נשמע קרוב לרפאל.", [])
n("עירא", "עירא הוא שם מקראי. בספר שמואל עירא היאירי היה כוהן לדוד המלך, ועירא היה גם שמם של שניים מגיבורי דוד. השם ניתן לבנים, והוא נדיר. בצליל הוא קרוב למילים עיר ער.", ["עורי"])
n("מוראל", "מוראל הוא שם עברי חדש, וכנראה הוא בנוי מהמילים מור ואל. במילה העברית מורל יש גם משמעות של רוח טובה ושל כוח פנימי. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", ["מור", "מורל"])
n("אחווה", "אחווה הוא שם עברי מהמילה אחווה, קרבה ואחדות כמו בין אחים. השם נשמע חם ומשפחתי, והוא נדיר. השם ניתן לבנות, וקרובים אליו בצליל השמות אחיה ואחיאל.", ["אחיה"])
n("צבר", "צבר הוא צמח קוצני שהפרי שלו מתוק. בעברית צבר הוא גם כינוי לילידי הארץ, קוצניים מבחוץ ומתוקים מבפנים. השם ניתן לבנים, והוא נדיר, אבל יש בו גאווה מקומית.", [])
n("רפי", "רפי הוא צורת חיבה של רפאל, שם עברי שפירושו אלוהים ירפא. רפאל הוא גם אחד המלאכים במסורת. רפי היה נפוץ מאוד בארץ בשנות החמישים והשישים, והוא ניתן לבנים.", ["רפאל"])
