n("אלאיה", "אלאיה הוא שם חדש ונדיר, וכנראה הוא צירוף של המילה אל ושל השם איה, ציפור דורסת. הצליל שלו רך ומוזיקלי. השם ניתן לבנות, והוא קרוב בצליל לשמות כמו אליה ואלה.", ["אליה", "איה"])
n("לנואל", "לנואל הוא שם עברי חדש ונדיר, וכנראה הוא בנוי מהמילים לנו ואל, ופירושו אלוהים שלנו. השם נשמע כמו הצהרה של אמונה. הוא ניתן גם לבנים וגם לבנות.", [])
n("בראנדל", "בראנדל הוא שם ביידיש, וכנראה הוא בא מהמילה בראנד, אש או בעירה. ביידיש נבנו צורות חיבה רבות עם הסיומת ל. השם ניתן לבנות, והוא נדיר מאוד היום.", [])
n("גלינה", "גלינה הוא שם רוסי ממקור יווני, ופירושו כנראה שלווה ושקט של הים. השם היה נפוץ מאוד בברית המועצות, וצורת החיבה שלו היא גליה. בארץ השם הגיע עם העלייה, והוא ניתן לבנות.", ["גליה"])
n("ארקדי", "ארקדי הוא שם רוסי ממקור יווני, שקשור לארקדיה, אזור בפלופונס שנחשב לארץ של שלווה כפרית. ברוסית השם מוכר, וצורת החיבה שלו היא ארקשה. בארץ השם הגיע עם העלייה, והוא ניתן לבנים.", [])
n("דיקלה", "דיקלה הוא כתיב של דקלה, שם עברי מהמילה דקל, עץ התמר. העץ הזה היה סמל של הארץ ושל שפע. השם ניתן לבנות, והוא היה נפוץ בארץ בשנות השבעים והשמונים.", ["דקלה", "דקל"])
n("חזי", "חזי הוא צורת חיבה של יחזקאל, שם עברי שפירושו אלוהים יחזק. יחזקאל הוא גם אחד הנביאים הגדולים. חזי היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנים.", ["יחזקאל"])
n("אפי", "אפי הוא צורת חיבה של אפרים, שם שקשור לשורש פ־ר־ה, פריון ושפע. אפרים הוא בנו של יוסף ושמו של אחד משבטי ישראל. אפי היה נפוץ בארץ בשנות השבעים, והוא ניתן לבנים.", ["אפרים"])
